#!/usr/bin/env python3
from __future__ import annotations

import argparse
import base64
import datetime as _dt
import shutil
import subprocess
import sys
import tempfile
from pathlib import Path


VERSION = "0.6.0"

OLD_GENERATOR = base64.b64decode('').decode("utf-8")
NEW_GENERATOR = base64.b64decode('').decode("utf-8")
UPDATE_NOTE = base64.b64decode('').decode("utf-8")
README_SECTION = base64.b64decode('').decode("utf-8")


def resolve_roots(frontend_arg, backend_arg):
    cwd = Path.cwd().resolve()

    frontend_candidates = []
    backend_candidates = []

    if frontend_arg:
        frontend_candidates.append(Path(frontend_arg).expanduser().resolve())
    if backend_arg:
        backend_candidates.append(Path(backend_arg).expanduser().resolve())

    frontend_candidates += [
        cwd,
        cwd / "LambdaVisionSuper",
        cwd.parent / "LambdaVisionSuper",
    ]
    backend_candidates += [
        cwd,
        cwd / "LambdaVisionSuperBackEnd",
        cwd.parent / "LambdaVisionSuperBackEnd",
    ]

    frontend = next(
        (
            path
            for path in frontend_candidates
            if (path / "tools/generate_llm_context_map.py").exists()
            and (path / "src/App.tsx").exists()
        ),
        None,
    )

    backend = next(
        (
            path
            for path in backend_candidates
            if (path / "app/main.py").exists()
            and (path / "app/services").exists()
        ),
        None,
    )

    if frontend is None:
        raise RuntimeError(
            "Cannot locate LambdaVisionSuper frontend. "
            "Use --frontend /path/to/LambdaVisionSuper"
        )

    if backend is None:
        raise RuntimeError(
            "Cannot locate LambdaVisionSuperBackEnd. "
            "Use --backend /path/to/LambdaVisionSuperBackEnd"
        )

    return frontend, backend


def generator_state(frontend):
    path = frontend / "tools/generate_llm_context_map.py"

    if not path.exists():
        return "MISSING"

    current = path.read_text(encoding="utf-8")

    if current == NEW_GENERATOR:
        return "OK"

    if current == OLD_GENERATOR:
        return "UPDATE"

    # Allow safe upgrade when the installed v0.5 generator is semantically
    # identical but whitespace differs slightly.
    required_old_signatures = (
        "IGNORED_DIRS =",
        "def collect_files(root: Path)",
        "def write_map(",
        "# Lambda Vision — Full System File Map",
    )

    if all(signature in current for signature in required_old_signatures):
        return "UPDATE-SIGNATURE"

    return "CONFLICT"


def backup(frontend, backend, paths):
    stamp = _dt.datetime.now().strftime("%Y%m%d_%H%M%S")
    root = (
        frontend
        / ".lambda_updater_backups"
        / f"llm_context_generator_v0060_{stamp}"
    )
    root.mkdir(parents=True, exist_ok=True)

    for path in paths:
        if not path.exists():
            continue

        try:
            rel = path.relative_to(frontend)
            destination = root / "frontend" / rel
        except ValueError:
            rel = path.relative_to(backend)
            destination = root / "backend" / rel

        destination.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(path, destination)

    return root


def ensure_readme(frontend):
    path = frontend / "docs/llm_context/README.md"
    path.parent.mkdir(parents=True, exist_ok=True)

    if not path.exists():
        path.write_text(
            "# Lambda Vision LLM Context\n\n" + README_SECTION.strip() + "\n",
            encoding="utf-8",
        )
        return "CREATE"

    text = path.read_text(encoding="utf-8")

    if "## Generator v2 handoff workflow" in text:
        return "OK"

    separator = "" if text.endswith("\n") else "\n"
    path.write_text(
        text + separator + "\n" + README_SECTION.strip() + "\n",
        encoding="utf-8",
    )
    return "APPEND"


def run_generator(frontend, backend, output_dir=None):
    generator = frontend / "tools/generate_llm_context_map.py"
    output_dir = output_dir or (frontend / "docs/llm_context")

    result = subprocess.run(
        [
            sys.executable,
            str(generator),
            "--frontend",
            str(frontend),
            "--backend",
            str(backend),
            "--output-dir",
            str(output_dir),
        ],
        cwd=str(frontend),
        text=True,
        capture_output=True,
    )

    if result.returncode != 0:
        raise RuntimeError(
            "Context generator failed:\n"
            + (result.stdout + "\n" + result.stderr).strip()
        )

    if result.stdout.strip():
        print(result.stdout.strip())


def scan(frontend, backend):
    print("=" * 88)
    print("LAMBDA VISION LLM CONTEXT GENERATOR V2 / UPDATE V0.6.0")
    print("=" * 88)
    print(f"Frontend : {frontend}")
    print(f"Backend  : {backend}")
    print()

    state = generator_state(frontend)
    print(f"  [{state:16}] frontend/tools/generate_llm_context_map.py")

    docs = [
        "SYSTEM_CONTEXT_INDEX.md",
        "SYSTEM_ARCHITECTURE.md",
        "SYSTEM_CONTEXT_BUNDLES.md",
        "SYSTEM_FILE_MAP.md",
    ]

    for name in docs:
        path = frontend / "docs/llm_context" / name
        print(
            f"  [{'REFRESH' if path.exists() else 'GENERATE':16}] "
            f"frontend/docs/llm_context/{name}"
        )

    note = (
        frontend
        / "docs/llm_context/updates/v0060_context_generator_v2.md"
    )
    print(
        f"  [{'OK' if note.exists() and note.read_text(encoding='utf-8') == UPDATE_NOTE else 'WRITE':16}] "
        "frontend/docs/llm_context/updates/v0060_context_generator_v2.md"
    )

    print()
    print("v2 improvements:")
    print("  - Source/config inventory instead of raw filesystem dump.")
    print("  - Excludes NPZ/model/data/image/runtime/build noise.")
    print("  - Project-aware module classification.")
    print("  - Encodes Legacy Sequencer vs Vision LAB architecture boundary.")
    print("  - Derives internal module dependencies from imports.")
    print("  - Extracts FastAPI and React routes.")
    print("  - Generates compact handoff index + architecture + bundles + file map.")
    print("  - Reports unclassified files so the generator can be improved iteratively.")

    if state == "CONFLICT":
        print()
        print("[WARN] Local generator modifications detected; apply will stop safely.")

    return 0


def apply(frontend, backend):
    state = generator_state(frontend)

    if state == "CONFLICT":
        raise RuntimeError(
            "Safe update stopped: tools/generate_llm_context_map.py "
            "differs from the known v0.5 generator. Merge local changes first."
        )

    generator = frontend / "tools/generate_llm_context_map.py"
    readme = frontend / "docs/llm_context/README.md"
    note = (
        frontend
        / "docs/llm_context/updates/v0060_context_generator_v2.md"
    )

    generated_docs = [
        frontend / "docs/llm_context/SYSTEM_CONTEXT_INDEX.md",
        frontend / "docs/llm_context/SYSTEM_ARCHITECTURE.md",
        frontend / "docs/llm_context/SYSTEM_CONTEXT_BUNDLES.md",
        frontend / "docs/llm_context/SYSTEM_FILE_MAP.md",
    ]

    backup_root = backup(
        frontend,
        backend,
        [generator, readme, note, *generated_docs],
    )

    generator.parent.mkdir(parents=True, exist_ok=True)
    generator.write_text(NEW_GENERATOR, encoding="utf-8")
    print("[WRITE] frontend/tools/generate_llm_context_map.py")

    note.parent.mkdir(parents=True, exist_ok=True)
    note.write_text(UPDATE_NOTE, encoding="utf-8")
    print("[WRITE] frontend/docs/llm_context/updates/v0060_context_generator_v2.md")

    action = ensure_readme(frontend)
    print(f"[{action}] frontend/docs/llm_context/README.md")

    run_generator(frontend, backend)

    print(f"[OK] Backup: {backup_root}")
    print("Run verify next.")
    return 0


