    write(frontend, "src/Pages/SequencerPage.tsx", "export const SequencerPage = () => null;")
    write(frontend, "src/Pages/InspectionPage.tsx", "export const InspectionPage = () => null;")
    write(frontend, "src/Pages/FleetDashboard.tsx", "export const FleetDashboard = () => null;")
    write(frontend, "src/Pages/DatabasePage.tsx", "export const DatabasePage = () => null;")
    write(frontend, "src/api/imageLabApi.ts", "export const ImageLabAPI = {};")
    write(frontend, "src/api/labServiceApi.ts", "export const LabServiceAPI = {};")
    write(frontend, "src/api/nodeApi.ts", "export const NodeAPI = {};")
    write(frontend, "src/api/fleetApi.ts", "export const FleetAPI = {};")
    write(frontend, "src/api/dbEngineApi.ts", "export const DB = {};")
    write(frontend, "src/components/VisionLabs/ImageProcessing/useImageLabController.ts", "export const useImageLabController = () => ({});")
    write(frontend, "src/components/VisionLabs/ImageProcessing/OperatorLibrary.tsx", "export const OperatorLibrary = () => null;")
    write(frontend, "src/Stores/FlowStore.tsx", "export const FlowStore = {};")
    write(frontend, "src/utils/FlowCompiler.ts", "export const FlowCompiler = {};")
    write(frontend, "package.json", '{"name":"mock"}')
