def verify(frontend, backend):
    print("=" * 88)
    print("VERIFY LAMBDA VISION LLM CONTEXT GENERATOR V2 / V0.6.0")
    print("=" * 88)

    failures = 0

    if generator_state(frontend) == "OK":
        print("[OK] Generator v2 installed")
    else:
        print("[FAIL] Generator v2 is not the installed target")
        failures += 1

    # Syntax check.
    generator = frontend / "tools/generate_llm_context_map.py"
    try:
        compile(generator.read_text(encoding="utf-8"), str(generator), "exec")
        print("[OK] Generator Python syntax")
    except Exception as exc:
        print(f"[FAIL] Generator Python syntax: {exc}")
        failures += 1

    # Regenerate real project docs.
    try:
        run_generator(frontend, backend)
        print("[OK] Real-project context compilation")
    except Exception as exc:
        print(f"[FAIL] Real-project context compilation: {exc}")
        failures += 1

    docs = {
        "SYSTEM_CONTEXT_INDEX.md": (
            "# Lambda Vision — LLM Context Index",
            "Critical architecture boundary",
        ),
        "SYSTEM_ARCHITECTURE.md": (
            "# Lambda Vision — System Architecture",
            "Legacy App Builder / Sequencer",
            "Image Processing LAB",
            "Lab Service",
        ),
        "SYSTEM_CONTEXT_BUNDLES.md": (
            "# Lambda Vision — LLM Context Bundles",
            "Image Processing LAB",
            "App Builder / Sequencer",
        ),
        "SYSTEM_FILE_MAP.md": (
            "# Lambda Vision — Source File Map",
            "Exclusion summary",
            "Generator coverage diagnostics",
        ),
    }

    for name, signatures in docs.items():
        path = frontend / "docs/llm_context" / name
        ok = path.exists()
        text = path.read_text(encoding="utf-8") if ok else ""
        ok = ok and all(signature in text for signature in signatures)
        print(f"[{'OK' if ok else 'FAIL'}] {name}")
        failures += 0 if ok else 1

    # Ensure the historical pollution is gone from the generated source map.
    file_map = (
        frontend / "docs/llm_context/SYSTEM_FILE_MAP.md"
    ).read_text(encoding="utf-8")

    if "`binary/data:.npz`" in file_map or ".npz" not in file_map:
        print("[OK] NPZ artifacts are excluded and only summarized")
    else:
        print("[FAIL] NPZ exclusion summary is missing")
        failures += 1

    if "_entropy1_train_ca/" not in "\n".join(
        line for line in file_map.splitlines()
        if line.startswith("| BE |") and "Full source inventory" not in line
    ):
        print("[OK] Runtime NPZ cache paths absent from source inventory")
    else:
        print("[FAIL] Runtime NPZ cache leaked into source inventory")
        failures += 1

    # Mock project regression: architecture classification + exclusion + routes.
    with tempfile.TemporaryDirectory() as temp:
        mock_root = Path(temp)
        mock_fe, mock_be = _create_mock_tree(mock_root)
        mock_out = mock_fe / "docs/llm_context"

        proc = subprocess.run(
            [
                sys.executable,
                str(generator),
                "--frontend",
                str(mock_fe),
                "--backend",
                str(mock_be),
                "--output-dir",
                str(mock_out),
            ],
            cwd=str(mock_fe),
            text=True,
            capture_output=True,
        )

        if proc.returncode != 0:
            print("[FAIL] Mock generator regression")
            print((proc.stdout + "\n" + proc.stderr).strip())
            failures += 1
        else:
            architecture = (
                mock_out / "SYSTEM_ARCHITECTURE.md"
            ).read_text(encoding="utf-8")
            mock_map = (
                mock_out / "SYSTEM_FILE_MAP.md"
            ).read_text(encoding="utf-8")

            assertions = [
                ("Legacy App Builder / Sequencer Runtime" in architecture, "legacy runtime classified"),
                ("Image Processing LAB Backend" in architecture, "Image LAB backend classified"),
                ("Lab Service Backend" in architecture, "Lab Service backend classified"),
                ("POST" in architecture and "/sessions" in architecture, "FastAPI routes extracted"),
                ("roi_001.npz" not in mock_map, "NPZ omitted from inventory"),
                ("output.jpg" not in mock_map, "image artifact omitted from inventory"),
                ("binary/data:.npz" in mock_map, "NPZ exclusion counted"),
            ]

            for ok, label in assertions:
                print(f"[{'OK' if ok else 'FAIL'}] Mock: {label}")
                failures += 0 if ok else 1

    if failures:
        print(f"[FAIL] Verification completed with {failures} issue(s).")
        return 1

    print("[OK] LLM Context Generator v2 / v0.6.0 verified.")
    return 0


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("command", choices=["scan", "apply", "verify", "generate"])
    parser.add_argument("--frontend")
    parser.add_argument("--backend")
    args = parser.parse_args()

    try:
        frontend, backend = resolve_roots(args.frontend, args.backend)

        if args.command == "scan":
            return scan(frontend, backend)

        if args.command == "apply":
            return apply(frontend, backend)

        if args.command == "generate":
            run_generator(frontend, backend)
            return 0

        return verify(frontend, backend)

    except Exception as exc:
        print(f"[ERROR] {exc}")
        return 2


if __name__ == "__main__":
    raise SystemExit(main())
